%%\ Lab 5: Edge Detection and Segmentation
% Course: Mathematical Algorithms (DSP) — Image Processing Labs
close all; clear; clc;

if ~exist('screenshots', 'dir')
    mkdir('screenshots');
end

if exist('peppers.png', 'file')
    I = im2double(rgb2gray(imread('peppers.png')));
else
    I = im2double(imread('cameraman.tif'));
end

%%\ 1) Basic derivative filters (Sobel, Prewitt)
edges_sobel   = edge(I, 'Sobel');
edges_prewitt = edge(I, 'Prewitt');

f1 = figure; %[output:3db3de44]
montage({edges_sobel, edges_prewitt}, 'Size', [1 2]); %[output:3db3de44]
title('Sobel | Prewitt edges'); %[output:3db3de44]
saveas(f1, fullfile('screenshots', '01_sobel_prewitt.png')); %[output:3db3de44]

%%\ 2) Canny detector (multi-stage)
edges_canny = edge(I, 'Canny', [0.05 0.2]);

f2 = figure; %[output:6f05b138]
imshow(edges_canny); %[output:6f05b138]
title('Canny edges'); %[output:6f05b138]
saveas(f2, fullfile('screenshots', '02_canny_edges.png')); %[output:6f05b138]

%%\ 3) Laplacian of Gaussian (LoG)
edges_log = edge(I, 'log');

f3 = figure; %[output:0fe760e1]
imshow(edges_log); %[output:0fe760e1]
title('Laplacian of Gaussian edges'); %[output:0fe760e1]
saveas(f3, fullfile('screenshots', '03_log_edges.png')); %[output:0fe760e1]

%%\ 4) Edge map -> segmentation (Otsu threshold)
level = graythresh(I); % Otsu automatic global threshold
BW    = imbinarize(I, level);

f4 = figure; %[output:390235df]
montage({I, BW}, 'Size', [1 2]); %[output:390235df]
title('Original | Otsu threshold binary mask'); %[output:390235df]
saveas(f4, fullfile('screenshots', '04_otsu_mask.png')); %[output:390235df]

%%\ 5) Label and visualize regions
[L, num] = bwlabel(BW);
RGB      = label2rgb(L, 'jet', 'k', 'shuffle');

f5 = figure; %[output:1fc685a4]
imshow(RGB); %[output:1fc685a4]
title(['Labeled regions: ', num2str(num)]); %[output:1fc685a4]
saveas(f5, fullfile('screenshots', '05_labeled_regions.png')); %[output:1fc685a4]

%%\ Print Summary Metrics for README.md
fprintf('\n--- Lab 5 Quantitative Summary ---\n'); %[output:00cbaffd]
fprintf('Sobel Edge Pixels   : %d\n', nnz(edges_sobel)); %[output:5b8f54da]
fprintf('Prewitt Edge Pixels : %d\n', nnz(edges_prewitt)); %[output:664a704f]
fprintf('Canny Edge Pixels   : %d\n', nnz(edges_canny)); %[output:44e0645c]
fprintf('LoG Edge Pixels     : %d\n', nnz(edges_log)); %[output:875a8535]
fprintf('Otsu Threshold Level: %.4f\n', level); %[output:8b5bc9e7]
fprintf('Labeled Regions     : %d\n', num); %[output:1007110c]

